@namespace sv_b2601232997f4ce0bffc8cfd99f593e0.Components.Pages.Catalog
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<div class="container-fluid">
    <h3 class="mb-3">Product Catalog</h3>

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="alert alert-danger" role="alert">
            <strong>Error:</strong> @errorMessage
            <button class="btn btn-sm btn-outline-danger ms-2" @onclick="RetryLoad">Retry</button>
        </div>
    }
    else
    {
        <div class="row">
            <!-- Sidebar Filters -->
            <div class="col-lg-3">
                <CatalogFilters Categories="categories"
                                OnFiltersApplied="HandleFiltersApplied"
                                OnFiltersCleared="HandleFiltersCleared" />
            </div>

            <!-- Main Content -->
            <div class="col-lg-9">
                @if (isLoading)
                {
                    <div class="text-center py-5">
                        <div class="spinner-border text-primary" role="status">
                            <span class="visually-hidden">Loading...</span>
                        </div>
                        <p class="mt-2 text-muted">Loading products…</p>
                    </div>
                }
                else if (result is not null && result.Items.Count > 0)
                {
                    <CatalogToolbar SortBy="@sortBy"
                                    TotalCount="result.TotalCount"
                                    Page="result.Page"
                                    PageSize="result.PageSize"
                                    OnSortChanged="HandleSortChanged" />

                    <ProductGrid Products="result.Items"
                                 OnProductSelected="HandleProductSelected"
                                 OnAddToCart="HandleAddToCart" />

                    <CatalogPagination Page="result.Page"
                                       TotalCount="result.TotalCount"
                                       PageSize="result.PageSize"
                                       OnPageChanged="HandlePageChanged" />
                }
                else
                {
                    <div class="text-center py-5">
                        <p class="text-muted fs-5">No products found matching your filters.</p>
                        <button class="btn btn-outline-primary" @onclick="HandleFiltersCleared">Clear Filters</button>
                    </div>
                }
            </div>
        </div>
    }
</div>

@code {
    /// <summary>Raised when a product card is clicked for navigation to detail.</summary>
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private List<string> categories = [];
    private PagedResult<Product>? result;
    private ProductFilter currentFilter = new(null, null, null, false);
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private const int PageSize = 9;
    private bool isLoading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadDataAsync();
    }

    private async Task LoadDataAsync()
    {
        try
        {
            isLoading = true;
            errorMessage = null;

            var categoriesTask = ProductService.GetCategoriesAsync();
            var searchTask = ProductService.SearchAsync(currentFilter, sortBy, currentPage, PageSize);
            await Task.WhenAll(categoriesTask, searchTask);

            categories = await categoriesTask;
            result = await searchTask;
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task SearchAsync()
    {
        try
        {
            isLoading = true;
            errorMessage = null;
            result = await ProductService.SearchAsync(currentFilter, sortBy, currentPage, PageSize);
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task HandleFiltersApplied(ProductFilter filter)
    {
        currentFilter = filter;
        currentPage = 1;
        await SearchAsync();
    }

    private async Task HandleFiltersCleared()
    {
        currentFilter = new ProductFilter(null, null, null, false);
        currentPage = 1;
        await SearchAsync();
    }

    private async Task HandleSortChanged(string newSort)
    {
        sortBy = newSort;
        currentPage = 1;
        await SearchAsync();
    }

    private async Task HandlePageChanged(int page)
    {
        currentPage = page;
        await SearchAsync();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder for cart integration
        return Task.CompletedTask;
    }

    private async Task RetryLoad() => await LoadDataAsync();
}

